// Crate navigation, direct card actions, and an overview-first organizer.
const crateMark=()=>'<svg class="crate-mark" viewBox="0 0 24 24" aria-hidden="true" style="shape-rendering:crispEdges"><path fill="#e7a170" stroke="none" d="M3 6h3V4h3V2h6v2h3v2h3v12h-3v2h-3v2H9v-2H6v-2H3z"/><path fill="#a35d35" stroke="none" d="M12 10h3V8h3V6h3v12h-3v2h-3v2h-3z"/><path fill="#f2c383" stroke="none" d="M6 6h3V4h6v2h3v2h-3v2H9V8H6z"/><path fill="#513c27" stroke="none" d="M3 8h3v2h3v2h3v8H9v-6H6v-2H3zm12 4h3v-2h3v3h-3v5h-3zM9 3h3v3h3v3h-3V7H9z"/></svg>';
let overviewMode=true;
// One-pixel grid tracks let following cards rise beneath shorter cards.
const cardSizes=new ResizeObserver(entries=>{for(const {target} of entries){const span=Math.ceil(target.getBoundingClientRect().height+14);if(target.style.gridRowEnd!==`span ${span}`)target.style.gridRowEnd=`span ${span}`;}});
function observeCards(){cardSizes.disconnect();$('items').querySelectorAll('.item').forEach(card=>{card.style.gridRowEnd=`span ${Math.ceil(card.getBoundingClientRect().height+14)}`;cardSizes.observe(card)});}

function refreshCrateBrowse(){const host=$('crate-browse');host.innerHTML=`<button type="button" data-browse="all" aria-pressed="${!onlyCategory}">${crateMark()}<span>Storage room</span></button>`+categories.map(c=>`<button type="button" data-browse="${c.id}" aria-pressed="${onlyCategory&&categories[selected]?.id===c.id}">${iconHTML(c.icon,c.color,19,c.drawing)}<span>${esc(c.name)}</span></button>`).join('');}
function recordCards(record){return InnSurface.cards(categories.find(c=>c.id===record.category))}
render=function(){const q=$('search').value.trim(),days=Number($('date-filter').value||0),items=data().filter(x=>(!days||x.createdAt>=Date.now()-days*86400000)&&(q||!onlyCategory||(x.category===categories[selected]?.id||(!categories.some(c=>c.id===x.category)&&categories[selected]?.id==='inbox')))&&InnContent.matches(x,q));
  $('category-filter').innerHTML=crateMark()+'<span>Storage room</span>';$('category-filter').setAttribute('aria-pressed',String(!onlyCategory));$('recents-heading').textContent=q?'Search · Storage room':onlyCategory?categories[selected]?.name:'Recents';refreshCrateBrowse();window.InnSync?.badge();
  const layouts=items.map(recordCards).map(s=>s.layout);$('items').dataset.layout=layouts.includes('large')?'large':layouts.length&&layouts.every(x=>x==='compact')?'compact':'small';
  $('items').innerHTML=items.length?items.map(x=>{const c=categories.find(c=>c.id===x.category)||categories[0],settings=recordCards(x),date=x.createdAt?new Date(x.createdAt):null,stamp=date?date.toLocaleDateString(undefined,{month:'short',day:'numeric'})+' · '+date.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}):'Sample';const body=InnContent.note(x,settings),thumb=settings.media&&x.images?.length?`<div class="card-images">${imageMarkup(x.images[0])}${x.images.length>1?`<span class="image-count">+${x.images.length-1}</span>`:''}</div>`:'',metadata=settings.preview&&x.url?x.metadata:null;
    const image=metadata&&settings.media&&safeURL(metadata.image)?`<img class="card-url-image" src="${esc(metadata.image)}" referrerpolicy="no-referrer" alt="" loading="lazy">`:'';
    const title=settings.title&&!InnContent.generatedTitle(x)?`<h3>${esc(metadata?.title||x.title||'Untitled')}</h3>`:'';
    const content=thumb+image+`<span class="item-type">${x.pinned?'★ ':''}${iconHTML(x.type==='link'?'ArrowUpRight':x.type==='image'?'Image':x.type==='audio'?'Mic':x.type==='video'?'Film':'FileText',c.color,16)}${x.conflict?' Conflict copy':''}</span>`+title+(settings.domain&&x.url?`<span class="link-domain">${esc(safeURL(x.url)?.hostname||'')}</span>`:'')+(settings.body&&(body||metadata?.description)?`<p>${esc(body||metadata.description)}</p>`:'');
    const label=x.url?'Open source: '+(x.metadata?.title||x.title):x.type==='image'?'Copy image: '+x.title:x.type==='audio'||x.type==='video'?'Play: '+x.title:'Copy: '+x.title;
    const mediaCard=['audio','video'].includes(x.type);const playback=mediaCard&&settings.media?(x.media||[]).map(f=>f.blob?`<${f.type?.startsWith('video/')?'video':'audio'} controls preload="none" src="${imageURL(f)}" aria-label="Play recording"></${f.type?.startsWith('video/')?'video':'audio'}>`:'<span class="small-note">Recording on capture device</span>').join(''):'';const transcript=settings.transcript&&x.transcript?`<div class="transcript-content"><p class="card-transcript">${esc(x.transcript)}</p><button type="button" data-copy-transcript="${x.id}" aria-label="Copy transcript">${iconHTML('Copy',null,16)}</button></div>`:'';
    const main=mediaCard?`<div class="card-main media-content">${playback}${transcript}${content}</div>`:x.url?`<a class="card-main" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(label)}">${content}</a>`:`<button type="button" class="card-main" data-card-action="${x.id}" aria-label="${esc(label)}">${content}</button>`;
    return `<article class="item layout-${settings.layout}" data-record="${x.id}">${main}${!mediaCard?transcript:''}<div class="card-bottom"><button type="button" class="card-info" data-open="${x.id}" aria-label="Edit and info: ${esc(x.title)}">${iconHTML('Ellipsis',null,18)}</button>${x.url?`<button type="button" class="card-copy" data-copy-link="${x.id}" aria-label="Copy link: ${esc(x.title)}">${iconHTML('Copy',null,15)}</button>`:''}<div class="item-meta">${settings.crate?`<span class="card-category">${iconHTML(c.icon,c.color,15,c.drawing)}${esc(c.name)}</span>`:''}${settings.date&&date?`<time datetime="${date.toISOString()}" title="${esc(date.toLocaleString())}">${esc(stamp)}</time>`:''}</div></div></article>`;
  }).join(''):`<div class="empty">${q?'Nothing by that name.':onlyCategory?'Room for something.':'Your next good find goes here.'}</div>`;
  observeCards();
};
const originalSetSelected=setSelected;setSelected=function(i){onlyCategory=true;originalSetSelected(i);InnSurface.select(categories[selected]);};
$('category-filter').onclick=()=>{onlyCategory=false;InnSurface.select(null);render()};
$('crate-browse').onclick=e=>{const b=e.target.closest('[data-browse]');if(!b)return;if(b.dataset.browse==='all')$('category-filter').click();else selectCategory(categories.findIndex(c=>c.id===b.dataset.browse));};
$('appearance').textContent='Make it yours';$('appearance').onclick=()=>InnSurface.open('global');
InnSurface.configure(()=>categories,async(id,appearance)=>{const i=categories.findIndex(c=>c.id===id),next=Protocol.revised({...categories[i],appearance});const old=categories[i];categories[i]=next;try{persistCrates()}catch(error){categories[i]=old;throw error}notifyLocalChange();render()});addEventListener('inn:appearance',()=>{applyGeneralPreferences();render()});addEventListener('inn:cards-preview',()=>render());
async function copyRecord(record,kind){try{if(kind==='image'){const file=record.images?.find(x=>x.blob);if(!file)throw Error('The original image is on its capture device.');if(!navigator.clipboard?.write||!window.ClipboardItem)throw Error('Image copying is unavailable here. Open info to download the original.');const pngPromise=(async()=>{if(file.blob.type==='image/png')return file.blob;const bitmap=await createImageBitmap(file.blob),canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;canvas.getContext('2d').drawImage(bitmap,0,0);bitmap.close();return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Couldn’t copy image.')),'image/png'))})();await navigator.clipboard.write([new ClipboardItem({'image/png':pngPromise})]);}else{const text=kind==='link'?record.url:kind==='transcript'?record.transcript:record.body||record.title;await navigator.clipboard.writeText(text||'')}toast('Copied.')}catch(error){toast(error.message||'Clipboard access is unavailable. Try the copy button in info.')}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-card-action],[data-copy-link],[data-copy-transcript]');if(!b)return;const record=data().find(x=>x.id===(b.dataset.cardAction||b.dataset.copyLink||b.dataset.copyTranscript));if(!record)return;if(b.dataset.copyTranscript)copyRecord(record,'transcript');else if(b.dataset.copyLink)copyRecord(record,'link');else if(['audio','video'].includes(record.type))detail(record.title,record.body,record.type,record.url,record);else copyRecord(record,record.type==='image'?'image':'text')});
const originalDetail=detail;detail=function(title,body,type,url,record){originalDetail(title,body,type,url,record);$('detail-added').textContent=record?.createdAt?'Added '+new Date(record.createdAt).toLocaleString():'';$('detail-transcript').hidden=!record?.transcript;$('detail-transcript-text').textContent=record?.transcript||'';$('detail-copy-actions').hidden=!record;$('copy-text').hidden=!record?.body;$('copy-link').hidden=!record?.url;$('copy-image').hidden=!record?.images?.some(x=>x.blob);$('copy-transcript').hidden=!record?.transcript;};
for(const [id,kind] of [['copy-text','text'],['copy-link','link'],['copy-image','image'],['copy-transcript','transcript']])$(id).onclick=()=>{const r=notes.find(x=>x.id===activeSaveId);if(r)copyRecord(r,kind)};
const originalRefreshDetail=refreshDetail;refreshDetail=function(record){originalRefreshDetail(record);if($('detail-transcript')){$('detail-transcript').hidden=!record?.transcript;$('detail-transcript-text').textContent=record?.transcript||'';$('copy-transcript').hidden=!record?.transcript}};
$('auto-paste').onclick=async()=>{if(captureBusy)return;try{let text='',files=[];if(navigator.clipboard?.read){const contents=await navigator.clipboard.read();for(const item of contents){const imageType=item.types.find(t=>ACCEPTED_IMAGES.has(t));if(imageType){const blob=await item.getType(imageType);files.push(new File([blob],'Pasted image.'+imageType.split('/')[1],{type:imageType}))}else if(item.types.includes('text/plain'))text+=await (await item.getType('text/plain')).text();}}else text=await navigator.clipboard.readText();if(files.length)await addImages(files);if(text){$('capture').value+=($('capture').value?'\n':'')+text;schedulePreview()}if(!text&&!files.length){toast('Nothing to paste.');return}composer.requestSubmit();}catch{toast('Clipboard access needs permission. You can also paste with ⌘V / Ctrl+V.');$('capture').focus()}};
function renderCrateOverview(){$('crate-overview').innerHTML=categories.map(c=>`<button type="button" data-edit-crate="${c.id}">${iconHTML(c.icon,c.color,28,c.drawing)}<span>${esc(c.name)}</span><small>${notes.filter(x=>!x.deleted&&x.category===c.id).length}</small></button>`).join('')+`<button type="button" id="overview-add">＋<span>New crate</span></button>`;$('overview-add').onclick=()=>editCrate('new');const retired=$('retired-crates');retired.hidden=!archivedCategories.length;$('retired-crate-list').innerHTML=archivedCategories.map(c=>`<button type="button" data-restore-crate="${c.id}">${iconHTML(c.icon,c.color,20,c.drawing)}<span>${esc(c.name)}</span><span>Restore ↶</span></button>`).join('')}
function overview(){overviewMode=true;draft=null;$('crate-overview').hidden=false;$('category-form').hidden=true;$('crate-editor-toolbar').hidden=true;$('category-edit-select').hidden=true;$('category-editor-title').innerHTML=crateMark()+'Your crates';renderCrateOverview();InnMenus.watch($('category-editor'),()=>overviewMode?'overview':JSON.stringify({...draft,name:$('category-name').value}),()=> $('category-form').requestSubmit())}
function editCrate(id){overviewMode=false;$('crate-overview').hidden=true;$('category-form').hidden=false;$('crate-editor-toolbar').hidden=false;populateDraft(id);$('category-editor-title').textContent=id==='new'?'A new crate.':'A little crate.';$('delete-crate').hidden=id==='new'||id==='inbox';InnMenus.watch($('category-editor'),()=>JSON.stringify({...draft,name:$('category-name').value}),()=> $('category-form').requestSubmit());$('category-name').focus()}
openEditor=function(){overview();$('category-editor').showModal()};$('edit-categories').onclick=openEditor;$('new-category').onclick=()=>InnMenus.change($('category-editor'),()=>editCrate('new'));$('crate-overview').onclick=e=>{const b=e.target.closest('[data-edit-crate]');if(b)editCrate(b.dataset.editCrate)};$('back-to-crates').onclick=()=>InnMenus.change($('category-editor'),overview);
$('crate-appearance').onclick=()=>{if(draft?.id)InnSurface.open(draft.id);else toast('Save your crate first.')};
$('retired-crate-list').onclick=e=>{const b=e.target.closest('[data-restore-crate]');if(!b)return;const c=archivedCategories.find(c=>c.id===b.dataset.restoreCrate);if(!c)return;const restored=Protocol.revised({...c,deleted:false});categories.push(restored);archivedCategories=archivedCategories.filter(x=>x.id!==c.id);try{persistCrates();renderWheel();selectCategory(categories.length-1,false);overview();notifyLocalChange();toast('Crate restored.')}catch{categories=categories.filter(x=>x.id!==c.id);archivedCategories.push(c);toast('Couldn’t restore this crate.')}};
let deletingCrate=null;$('delete-crate').onclick=()=>{deletingCrate=draft.id;const count=notes.filter(x=>!x.deleted&&x.category===deletingCrate).length;$('delete-crate-heading').textContent='Retire '+draft.name+'?';$('delete-crate-count').textContent=count+' save'+(count===1?'':'s')+' inside.';$('move-crate-to').innerHTML=categories.filter(c=>c.id!==deletingCrate).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('delete-crate-mode').value='move';$('move-crate-row').hidden=false;$('delete-crate-result').textContent='';$('delete-crate-dialog').showModal()};$('delete-crate-mode').onchange=()=>{$('move-crate-row').hidden=$('delete-crate-mode').value!=='move'};
$('delete-crate-form').onsubmit=async e=>{e.preventDefault();const id=deletingCrate,mode=$('delete-crate-mode').value,destination=mode==='move'?$('move-crate-to').value:'inbox',button=$('confirm-delete-crate');button.disabled=true;try{const all=await allLocalRecords(),changed=all.map(r=>r.category===id?Protocol.revised({...r,category:destination,deleted:mode==='trash'?true:r.deleted}):r),retired=categories.find(c=>c.id===id),nextArchive=Protocol.revised({...retired,deleted:true});await persistRecords(changed);const previous=categories;categories=categories.filter(c=>c.id!==id);archivedCategories.push(nextArchive);try{persistCrates()}catch(error){categories=previous;archivedCategories=archivedCategories.filter(c=>c.id!==id);await persistRecords(all);throw error}selected=0;renderWheel();selectCategory(0,false);$('delete-crate-dialog').close();overview();notifyLocalChange();toast(mode==='trash'?'Crate retired. Saves are in Trash.':'Crate retired. Saves moved.')}catch{$('delete-crate-result').textContent='Couldn’t finish. Your crate is still available.'}finally{button.disabled=false}};
const originalEdit=$('edit-save').onclick;$('edit-save').onclick=()=>{originalEdit();if(!$('edit-category').value)$('edit-category').value='inbox';InnMenus.watch($('edit-record'),()=>JSON.stringify([$ ('edit-title').value,$('edit-body').value,$('edit-category').value,$('edit-tags').value]),()=> $('edit-record-form').requestSubmit())};
window.InnUI={refreshCrates(){refreshCrateBrowse();if($('category-editor').open&&overviewMode)renderCrateOverview()}};
onlyCategory=false;InnSurface.select(null);render();

// Resolve the current renderer at event time; old function references omitted transcripts.
$('search').oninput=()=>render();$('view-filter').onchange=()=>render();$('date-filter').onchange=()=>render();
function applyGeneralPreferences(){const g=InnSurface.export().general;document.body.dataset.wheelSide=g.wheelSide;const control=document.querySelector('.category-control');const narrow=matchMedia('(max-width: 560px)').matches;if(g.wheelPlacement==='below'||narrow)composer.append(control);else document.querySelector('.composer-entry').append(control);document.body.dataset.wheelPlacement=g.wheelPlacement==='below'||narrow?'below':'beside'}
applyGeneralPreferences();matchMedia('(max-width: 560px)').addEventListener('change',applyGeneralPreferences);
$('general-preferences').onclick=()=>InnSurface.open('global','general');

let beforeCustomizer=null;
addEventListener('inn:customizer-open',()=>{clearTimeout(settleTimer);beforeCustomizer={crateId:categories[selected]?.id,onlyCategory};});
addEventListener('inn:customizer-close',()=>{if(!beforeCustomizer)return;const saved=beforeCustomizer;beforeCustomizer=null;clearTimeout(settleTimer);const index=categories.findIndex(c=>c.id===saved.crateId);selectCategory(Math.max(0,index),false);onlyCategory=saved.onlyCategory;InnSurface.select(onlyCategory?categories[selected]:null);render();});
